        var itemId = $ax.repeater.getItemIdFromElementId(elementId);
        path[path.length - 1] = obj.parent.id;
        elementId = $ax.getElementIdFromPath(path, { itemNum: itemId });
        obj = $obj(elementId);
    }

    return elementId;
};

